def _steiner_dp(h, src, dsts, cap=12):
    """Exact directed Steiner tree via subset DP (Dreyfus-Wagner adapted
    to digraphs). dp[S][v] = cheapest tree rooted at v delivering to
    terminal set S, built by (a) merging proper bipartitions at v and
    (b) relaxing along graph edges (multi-source Dijkstra per subset).
    Returns (edge_set, cost) or None if too many terminals / no tree."""
    T = list(dict.fromkeys(dsts))
    if not T or len(T) > cap or src not in h or any(d not in h for d in T):
        return None
    k = len(T)
    idx = {d: 1 << i for i, d in enumerate(T)}
    full = (1 << k) - 1

    INF = float("inf")
    nodes = list(h.nodes())
    dp = {}      # subset -> {node: cost}
    choice = {}  # subset -> {node: ('base'|'merge'|'edge', ...)}

    def dijkstra_relax(S, dist):
        """Multi-source Dijkstra: relax dist[v] = min(dist[v], dist[u]+w(u,v))."""
        import heapq
        pq = [(c, v) for v, c in dist.items() if c < INF]
        heapq.heapify(pq)
        best = dict(dist)
        while pq:
            d, u = heapq.heappop(pq)
            if d > best.get(u, INF):
                continue
            for v in h[u]:
                nd = d + h[u][v]["cost"]
                if nd < best.get(v, INF) - 1e-12:
                    best[v] = nd
                    choice[S][v] = ("edge", u)
                    heapq.heappush(pq, (nd, v))
        return best

    # Iterate subsets in increasing popcount order.
    subsets = sorted(range(1, full + 1), key=lambda S: bin(S).count("1"))
    for S in subsets:
        dp[S] = {v: INF for v in nodes}
        choice[S] = {}
        if bin(S).count("1") == 1:
            d = T[S.bit_length() - 1]
            dp[S][d] = 0.0
            choice[S][d] = ("base",)
        # Merge proper bipartitions (enumerate S1 < S2 to avoid duplicates).
        sub = (S - 1) & S
        while sub:
            S1, S2 = sub, S ^ sub
            if S1 < S2:
                d1, d2 = dp[S1], dp[S2]
                for v in nodes:
                    c = d1.get(v, INF) + d2.get(v, INF)
                    if c < dp[S][v] - 1e-12:
                        dp[S][v] = c
                        choice[S][v] = ("merge", S1)
            sub = (sub - 1) & S
        # Extend trees along graph edges (root shifts to any node).
        dp[S] = dijkstra_relax(S, {v: c for v, c in dp[S].items() if c < INF})

    if dp[full].get(src, INF) >= INF:
        return None

    # Reconstruct the tree edge set from choices (edges deduplicated).
    edges = set()

    def walk(S, v):
        ch = choice[S].get(v)
        if ch is None:
            return
        if ch[0] == "base":
            return
        if ch[0] == "merge":
            walk(ch[1], v)
            walk(S ^ ch[1], v)
        elif ch[0] == "edge":
            u = ch[1]
            edges.add((u, v))
